@Test
public void linuxCommandBuilderDriverTest() {
    JobSubmissionEvent event = mock(JobSubmissionEvent.class);
    Optional<Integer> memory = Optional.of(100);
    when(event.getDriverMemory()).thenReturn(memory);
    String actual = this.linuxCommandBuilder.buildDriverCommand(event);
    String expected = "/bin/sh -c \"unzip local.jar -d 'reef/'; {{JAVA_HOME}}/bin/java -Xmx100m -XX:PermSize=128m " + "-XX:MaxPermSize=128m -ea -classpath " + "c:\\driverpath1:c:\\driverpath2:reef/local/*:reef/global/*:driverclasspathsuffix " + "-Dproc_reef org.apache.reef.runtime.common.REEFLauncher reef/local/driver.conf\"";
    Assert.assertEquals(expected, actual);
}

